//! A custom `COPY ... FROM` format advertised by a VGI catalog.
//! Protocol type: CopyFromFormatInfo.
struct CopyFromFormatInfo {
	std::optional<std::string> comment{};
	std::map<std::string, std::string> tags{};
	//! The `FORMAT` identifier users type. Lives in a single global namespace shared with built-ins
	//! (`csv`/`parquet`/`json`) and every other attached catalog's formats — collisions are rejected at
	//! ATTACH by the extension.
	std::string format_name{};
	//! Registered name of the worker function that performs the read.
	std::string handler{};
	//! Serialized Arrow schema of the format's options, built from the handler's `Arg`-annotated arguments
	//! (same encoding as `FunctionInfo.arguments`); each field's metadata carries the option type / default
	//! / `vgi_doc` description. The reserved `file_path` positional is excluded.
	Bytes options{};
	//! `"from"` | `"to"` | `"both"` — which COPY direction(s) this format serves; surfaced so the C++
	//! `vgi_copy_formats()` diagnostic can split FROM vs TO and so registration wires the right callbacks.
	std::string direction = "from";
	//! Intrinsic documentation from the handler's `Meta.description`.
	std::string description{};
	//! COPY ... TO only — when true the worker requires rows in source order, so the extension uses a
	//! single-threaded sink (`REGULAR_COPY_TO_FILE`) instead of the default parallel sharded write. Set via
	//! `Meta.ordered = True` on a `CopyToFunction`. Ignored for readers.
	bool ordered{};
};
