//! Consolidated bind request for all function types.
//! Protocol type: BindRequest.
struct BindRequest {
	//! Registered name of the VGI function this message targets.
	std::string function_name{};
	//! The bound function `Arguments`.
	Bytes arguments{};
	//! Which kind of function is being bound (`FunctionType`).
	FunctionType function_type{};
	//! Serialized Arrow schema of the input table (`None` for table functions with no input).
	std::optional<Bytes> input_schema{};
	//! Serialized DuckDB session settings relevant to the function.
	std::optional<Bytes> settings{};
	//! Serialized resolved secret values the function declared it needs.
	std::optional<Bytes> secrets{};
	//! Opaque per-attach catalog session token (bytes) echoed back so the worker can scope catalog state to
	//! the attachment; `None` outside a catalog context.
	std::optional<Bytes> attach_opaque_data{};
	//! Opaque DuckDB transaction handle (bytes); `None` when not inside a transaction.
	std::optional<Bytes> transaction_opaque_data{};
	//! True when `secrets` carries already-resolved values, so the worker should not re-resolve them.
	bool resolved_secrets_provided{};
	//! Unit of the time-travel `AT (TIMESTAMP|VERSION ...)` clause for this scan, threaded through from
	//! DuckDB's per-reference bind; `None` when the scan has no AT clause. NOTE: for inline-bound
	//! (function-backed) tables the actual on_bind RPC runs once at attach with no AT, so this is `None`
	//! there; the per-scan AT is carried on the bind request embedded in each InitRequest, so functions
	//! should read it at init via `params.init_call.bind_call.at_value` (or the `ProcessParams.at_value`
	//! accessor), not at on_bind.
	std::optional<std::string> at_unit{};
	//! Value of the time-travel `AT` clause for this scan; `None` when the scan has no AT clause. See
	//! `at_unit` for the inline-bind caveat.
	std::optional<std::string> at_value{};
	//! The `COPY ... FROM` context (source format + path); `None` unless this bind/init opens a COPY-FROM
	//! scan.
	std::optional<CopyFromContext> copy_from{};
	//! The `COPY ... TO` context (destination format + path); `None` unless this bind/init opens a COPY-TO
	//! sink.
	std::optional<CopyToContext> copy_to{};
	//! Catalog schema that owns the function being bound. Set by the DuckDB extension from the schema entry
	//! the function was registered into, so a name registered in two schemas resolves to the right
	//! implementation. `None` for non-catalog callers (the legacy `Worker.functions` list), where lookup
	//! falls back to bare name.
	std::optional<std::vector<std::string>> schema_path{};
	//! Resolved name of each logical argument, aligned with the complete pre-execution argument order.
	//! Fixed parameters use their declared names, unnamed varargs contain `None`, and named varargs retain
	//! the caller-provided name. `None` means names are unavailable.
	std::optional<std::vector<std::optional<std::string>>> argument_names{};
};
