//! Consolidated init request for all function types.
//! Protocol type: InitRequest.
struct InitRequest {
	//! The originating `BindRequest` (function name, arguments, schemas).
	Bytes bind_call{};
	//! Serialized Arrow schema of the rows the function produces.
	Bytes output_schema{};
	//! Opaque per-bind state the worker returned from bind(), threaded back into later calls. Wire-facing
	//! bytes the framework produced from the typed `BindResult.opaque_data`; consumers reconstruct via
	//! `MyConcreteDataclass.deserialize_from_bytes(raw)`. See `BindResponse.opaque_data` in
	//! vgi/invocation.py for the full contract rationale.
	std::optional<Bytes> bind_opaque_data{};
	//! Column indices DuckDB wants projected from the function's output; `None` for scalar functions or
	//! when no projection pushdown.
	std::optional<std::vector<int64_t>> projection_ids{};
	//! Serialized filter predicates DuckDB pushed down to the scan; `None` when no filters apply.
	std::optional<LargeBytes> pushdown_filters{};
	//! Serialized join-key batches pushed down for join filtering; `None` when not applicable.
	std::optional<std::vector<LargeBytes>> join_keys{};
	//! Split tokens to redeem in this init, or None for an ordinary whole-scan init. Usually one; a client
	//! that bin-packs sends a whole group and expects them concatenated in the order given.
	std::optional<std::vector<LargeBytes>> split_tokens{};
	//! Plain fetch limit, or None. NOT `order_by_limit`, which is a field of the Top-N hint. DuckDB cannot
	//! supply this; DataFusion can.
	std::optional<int64_t> row_limit{};
	//! For table-in-out functions, which init phase (INPUT / FINALIZE / buffering) this request opens;
	//! `None` for other function types.
	std::optional<VgiInitPhase> phase{};
	//! For a buffered-table finalize stream, which state_id this stream serves. Required when
	//! `phase=TABLE_BUFFERING_FINALIZE`, `None` otherwise. Opaque bytes — the worker chose the encoding
	//! when its combine() returned the finalize_state_ids list.
	std::optional<Bytes> finalize_state_id{};
	//! Identifier for one query execution, stable across the coordinator and any secondary workers; keys
	//! worker-owned state. `None` for global init, set for secondary init.
	std::optional<Bytes> execution_id{};
	//! Opaque per-init state threaded back into the stream; same producer/wire/consumer contract as
	//! `bind_opaque_data`.
	std::optional<Bytes> init_opaque_data{};
	//! Stable, client-owned identity of the streaming table-in-out substream this request opens (per DuckDB
	//! PipelineExecutor). Rides every InitRequest a substream's worker builds — INPUT and FINALIZE — so a
	//! worker can locate that substream's accumulated state even when an HTTP load balancer routes its init
	//! / process / finalize to different backends. `None` for non-substream function types.
	std::optional<Bytes> substream_id{};
	//! Column name of the order-pushdown hint from DuckDB's RowGroupPruner optimizer; `None` when no hint.
	std::optional<std::string> order_by_column_name{};
	//! Sort direction of the order-pushdown hint; `None` when no hint.
	std::optional<VgiOrderByDirection> order_by_direction{};
	//! Null-ordering of the order-pushdown hint; `None` when no hint.
	std::optional<VgiNullOrder> order_by_null_order{};
	//! Row limit of the order-pushdown hint; `None` when no hint.
	std::optional<int64_t> order_by_limit{};
	//! Sample percentage of the TABLESAMPLE pushdown hint from DuckDB's SamplingPushdown optimizer; `None`
	//! when no hint.
	std::optional<double> tablesample_percentage{};
	//! Sample seed of the TABLESAMPLE pushdown hint; `None` when no hint.
	std::optional<int64_t> tablesample_seed{};
};
bool operator==(const InitRequest &a, const InitRequest &b);
inline bool operator!=(const InitRequest &a, const InitRequest &b) {
	return !(a == b);
}
