//! Request for the scan-planning phase that precedes per-split `init()`.
//! Protocol type: TableFunctionPlanRequest.
struct TableFunctionPlanRequest {
	//! The originating `BindRequest`.
	Bytes bind_call{};
	//! Opaque per-bind state the worker returned from bind().
	std::optional<Bytes> bind_opaque_data{};
	//! Column indices the client wants projected.
	std::optional<std::vector<int64_t>> projection_ids{};
	//! Serialized filter predicates.
	std::optional<LargeBytes> pushdown_filters{};
	//! Serialized join-key batches pushed down for join filtering.
	std::optional<std::vector<LargeBytes>> join_keys{};
	//! Plain fetch limit. NOT `order_by_limit` (which is a field of the Top-N hint). DuckDB cannot supply
	//! this — `TableFunctionInitInput` has no limit field — so it is always `None` from DuckDB; DataFusion
	//! supplies it from `TableProvider::scan(limit)`.
	std::optional<int64_t> row_limit{};
	//! Requested split size. The primary sizing lever: a worker should emit splits of comparable cost,
	//! because the client cannot see per-split cost and will claim them as interchangeable units.
	std::optional<int64_t> target_split_bytes{};
	//! Parallelism floor — a small but expensive table still needs enough splits to occupy the client's
	//! readers.
	std::optional<int64_t> min_splits{};
	//! Pagination cap (Trino `getNextBatch(maxSize)`), NOT a sizing hint.
	std::optional<int64_t> max_splits_per_response{};
	//! Resume point in the *enumeration of splits*. Distinct from `start_position`, which names a place in
	//! the *data*.
	std::optional<Bytes> cursor{};
	//! Conjunctive narrowing on a continuation. Narrows future splits only; splits already emitted under a
	//! looser filter stay valid.
	std::optional<LargeBytes> refined_filters{};
	//! False means more refinement may arrive, so the worker may hold back splits; True says stop waiting.
	bool filters_complete = true;
	//! Exclusive lower bound in the data; `None` = from the start.
	std::optional<Bytes> start_position{};
	//! Inclusive upper bound; `None` = "as of now", and the worker reports the frontier it resolved in
	//! `PlanResponse.end_position`.
	std::optional<Bytes> end_position{};
	//! Column of the order-pushdown hint.
	std::optional<std::string> order_by_column_name{};
	//! Direction of the order-pushdown hint.
	std::optional<VgiOrderByDirection> order_by_direction{};
	//! Null ordering of the order-pushdown hint.
	std::optional<VgiNullOrder> order_by_null_order{};
	//! Row limit of the Top-N order-pushdown hint.
	std::optional<int64_t> order_by_limit{};
	//! TABLESAMPLE percentage hint.
	std::optional<double> tablesample_percentage{};
	//! TABLESAMPLE seed hint.
	std::optional<int64_t> tablesample_seed{};
};
bool operator==(const TableFunctionPlanRequest &a, const TableFunctionPlanRequest &b);
inline bool operator!=(const TableFunctionPlanRequest &a, const TableFunctionPlanRequest &b) {
	return !(a == b);
}
